def remember(x, items=None):
    if items is None:
        items = []
    items.append(x)
    return items
print(remember(1), remember(2))  # [1] [2]

from flask import Flask, jsonify, abort
app = Flask(__name__)
tasks = [{"id": 1, "title": "Review", "done": False}]

@app.route("/tasks/<int:task_id>")
def get_task(task_id):
    found = [t for t in tasks if t["id"] == task_id]
    if not found:
        abort(404)
    return jsonify({"task": found[0]})
